const SW_BENCHMARK={year:2025,published:'2026-08-07',organization:{total:509.1,rows:[['기술/사업부문',242.4],['운영',86.9],['영업/마케팅',57.9],['연구소',53.8],['경영지원/전략기획',51.4],['고객지원 서비스',16.7]]},career:{total:399.8,rows:[['15년 이상',24.8],['10~15년 미만',57.5],['5~10년 미만',120.4],['3~5년 미만',138.4],['3년 미만',58.8]]},source:'https://spri.kr/posts/view/24012?code=stat_sw_software_reports',pdf:'https://spri.kr/download/23884'};
function benchmarkPanel(){const career=state.benchmark==='career',d=career?SW_BENCHMARK.career:SW_BENCHMARK.organization;return `<section class="panel benchmark-panel">${head('IT 업계 인력 구성 참고','과기정통부·SPRi 2025 SW산업실태조사','중소기업')}<div class="benchmark-tabs"><button data-benchmark="organization" class="${career?'':'selected'}">조직별 구성</button><button data-benchmark="career" class="${career?'selected':''}">경력별 구성</button></div><div class="horizontal">${d.rows.map(([label,n])=>`<div class="barrow"><span>${label}</span><div class="track"><div class="fill benchmark-fill" style="width:${n/d.total*100}%"></div></div><span class="barvalue">${pct(n,d.total)}</span></div>`).join('')}</div><p class="benchmark-note">${career?'SW 전문인력 399.8천 명 기준입니다. 업계 전체 경력이며 현재 회사 근속과 다릅니다. 반올림으로 항목 합계와 총계에 차이가 있습니다.':'SW부문 인력 509.1천 명 기준입니다. 공식 조직 분류이므로 우리 회사 직군과 동일한 분류가 아닙니다. 비중은 공표 인원에서 계산했습니다.'}</p><p class="source-line">2025년 기준 · 2026.08.07 게시 · 보고서 ${career?'25':'22'}쪽<br><a href="${SW_BENCHMARK.source}" target="_blank" rel="noopener">SPRi 원문</a> · <a href="${SW_BENCHMARK.pdf}#page=${career?37:34}" target="_blank" rel="noopener">통계표 확인</a></p></section>`;}
